import hashlib


def review_dir_args(reviewer_id, target_cli, cli_set, path, cyber):
    """Extra-folder read grant for the reviewer CLI, as two mutually exclusive
    slots so an unused slot renders as nothing (an empty quoted arg would become
    a stray positional). Placement is per CLI, from prompts_cyber.json
    reviewer_cli (NOT part of the hashed prompt)."""
    cfg = cyber.get("reviewer_cli", {}).get(reviewer_id, {})
    flag = cfg.get("flag", "")
    if not flag:
        return {"input_dir_prefix": "", "input_dir_suffix": ""}
    arg = flag + ' "' + f'{target_cli["container_path"]}/set_{cli_set["id"]}{path}' + '"'
    if cfg.get("placement", "suffix") == "prefix":
        return {"input_dir_prefix": arg, "input_dir_suffix": ""}
    return {"input_dir_prefix": "", "input_dir_suffix": arg}

LLM_SET = "a"

# Run knobs live in prompts_cyber.json -> run_config.
# Empty list or ["all"] = everything. target_models additionally accepts
# "self" (= the reviewer's own code), mixable with explicit ids, so a
# diagonal-only run is expressible: reviewers=["all"], target_models=["self"].
merged = _items[0]["json"]
main = merged["main_json"]
cyber = merged["cyber_json"]
run = cyber.get("run_config", {})

REVIEWERS = run.get("reviewers", [])
TARGET_FOLDERS = run.get("target_folders", [])
TARGET_TASKS = run.get("target_prompt_tasks_num", [])
TARGET_STYLES = run.get("target_prompt_style", [])
TARGET_MODELS = run.get("target_models", [])


def selected(value, allowed):
    return len(allowed) == 0 or "all" in allowed or value in allowed


def keep_task(value, allowed):
    # task numbers may be configured as ints or strings
    return (
        len(allowed) == 0
        or "all" in allowed
        or value in allowed
        or str(value) in [str(a) for a in allowed]
    )


def model_allowed(target_id, reviewer_id):
    # "self" expands per job to the reviewer's own id
    if len(TARGET_MODELS) == 0 or "all" in TARGET_MODELS:
        return True

    if target_id == reviewer_id and "self" in TARGET_MODELS:
        return True

    return target_id in TARGET_MODELS


students = main["student"]
cli_settings = main["cli_settings"]

# The review instruction is fixed - same prompt, same hash, applied to every cell.
# Join cyber config to main config by CLI name (order-independent).
cyber_by_name = {c["name"]: c for c in cyber["cli_settings"]}
review_prompt = cyber["analyst"][0]["task"][0]["prompts"][0]["prompt"]
review_hash = hashlib.sha256(
    review_prompt.encode("utf-8")
).hexdigest()

jobs = []

for student in students:
    folder = student["name"]

    # A folder is reviewed even when its owner is not selected as a reviewer
    if not selected(folder, TARGET_FOLDERS):
        continue

    for task in student["task"]:
        if not keep_task(task["task_number"], TARGET_TASKS):
            continue

        for prompt in task["prompts"]:
            style = prompt.get("style", "")

            if not selected(style, TARGET_STYLES):
                continue

            # Absorbs the removed 'If string not empty' node
            if not isinstance(prompt.get("prompt"), str) or prompt["prompt"].strip() == "":
                continue

            path = f'/{student["name"]}/{task["task_number"]}/{style}/'

            if prompt.get("turn") is not None:
                path += f'{prompt["turn"]}/'

            gen_hash = hashlib.sha256(
                prompt["prompt"].encode("utf-8")
            ).hexdigest()

            # Identical formula to before: changing either prompt invalidates a review
            benchmark_hash = hashlib.sha256(
                (gen_hash + review_hash).encode("utf-8")
            ).hexdigest()

            for reviewer_cli in cli_settings:
                reviewer_cyber = cyber_by_name.get(reviewer_cli["name"])
                if reviewer_cyber is None:
                    continue
                reviewer_id = reviewer_cyber["id"]

                if not selected(reviewer_id, REVIEWERS):
                    continue

                for target_cli in cli_settings:
                    target_cyber = cyber_by_name.get(target_cli["name"])
                    if target_cyber is None:
                        continue
                    target_id = target_cyber["id"]

                    if not model_allowed(target_id, reviewer_id):
                        continue

                    for cli_set in reviewer_cli["input"]["set"]:

                        # Only use the selected LLM set
                        if cli_set["id"] != LLM_SET:
                            continue

                        jobs.append({
                            # Traceability
                            "reviewer_id": reviewer_id,
                            "target_id": target_id,
                            "folder": folder,
                            "task_number": task["task_number"],
                            "style": style,

                            # Job fields downstream expressions read - names unchanged
                            "prompt": prompt["prompt"],
                            "hash": gen_hash,
                            "cyber_prompt": review_prompt,
                            "cyber_hash": review_hash,
                            "benchmark_cyber_hash": benchmark_hash,

                            "cli_settings": {
                                # CLI-level fields (reviewer's)
                                "name": reviewer_cli["name"],
                                "set_id": cli_set["id"],
                                "skill_path": reviewer_cyber["skill_path"],

                                # Flatten common input fields, excluding nested set
                                **{
                                    key: value
                                    for key, value in reviewer_cli["input"].items()
                                    if key != "set"
                                },

                                # Flatten selected set fields, excluding id
                                **{
                                    key: value
                                    for key, value in cli_set.items()
                                    if key != "id"
                                },

                                # Baseline path to copy code FROM = the target's folder
                                "container_path":
                                    f'{target_cli["container_path"]}/set_{cli_set["id"]}{path}',

                                # Extra-folder read grant (per-CLI flag + placement)
                                **review_dir_args(
                                    reviewer_id, target_cli, cli_set, path, cyber
                                ),

                                # Cyber path to copy into and write the review to =
                                # reviewer parent + target cell
                                "cyber_container_path":
                                    f'{reviewer_cyber["cyber_container_path"]}/{target_id}/set_{cli_set["id"]}{path}',

                                # Flatten json_output with json_output_ prefix
                                **{
                                    f"json_output_{key}": value
                                    for key, value in reviewer_cli["json_output"].items()
                                }
                            },
                        })

return jobs
